import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.CXroN2RO.js";const n="/study/images/graphics/swap-chain-image-lifecycle.svg",o="/study/images/graphics/swap-chain-presentation-modes.svg",m=JSON.parse('{"title":"スワップチェーンとVSync — 描画した絵が画面に出るまで","description":"","frontmatter":{"title":"スワップチェーンとVSync — 描画した絵が画面に出るまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"描画に使う画像を取得してから再取得できるまでを追い、FIFO・MAILBOX・IMMEDIATEで画面に出る絵と待ち時間を比べる。","aliases":["スワップチェーン","スワップチェイン","swap chain","swapchain","VSync","垂直同期","ティアリング","scanout","FIFO","MAILBOX","IMMEDIATE","VRR"],"verification":"VulkanのVkPresentModeKHR・画像取得・Presentの仕様と、DXGIのPresent・VRRの公式資料に照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/optimization/swap-chain-and-vsync.md","filePath":"graphics/optimization/swap-chain-and-vsync.md"}'),i={name:"graphics/optimization/swap-chain-and-vsync.md"};function d(c,e,l,h,p,g){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="スワップチェーンとvsync-—-描画した絵が画面に出るまで" tabindex="-1">スワップチェーンとVSync — 描画した絵が画面に出るまで <a class="header-anchor" href="#スワップチェーンとvsync-—-描画した絵が画面に出るまで" aria-label="Permalink to &quot;スワップチェーンとVSync — 描画した絵が画面に出るまで&quot;">​</a></h1><p>GPUが次の絵を描いている間にも、画面は前の絵を読み出しています。<strong>スワップチェーン</strong>は、アプリが描いた絵を表示側に渡し、使用が終わった画像を次の描画に使い回す仕組みです。**VSync（垂直同期）**を使うと、表示する画像の切り替えを画面の更新境界に合わせられます。切り替えを待つ間に複数の絵が届いたとき、古い絵から順に出すか、最新の候補を出すかで、画面に現れる絵が変わります。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPresentModeKHR.html" target="_blank" rel="noreferrer">KhronosのVulkan表示モード仕様</a></p><h2 id="_1枚の画像を取得してから、また使えるまで" tabindex="-1">1枚の画像を取得してから、また使えるまで <a class="header-anchor" href="#_1枚の画像を取得してから、また使えるまで" aria-label="Permalink to &quot;1枚の画像を取得してから、また使えるまで&quot;">​</a></h2><p>ゲームが描く画像と、表示側が使う画像を切り替える流れをVulkanで追います。ここでの「画像」は使い回す描画先です。毎フレーム新しい画像を確保する代わりに、アプリは使える画像の番号を取得します。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/vkAcquireNextImageKHR.html" target="_blank" rel="noreferrer">Vulkanの画像取得API</a></p><figure class="study-figure"><img src="'+n+'" alt="1枚の画像は取得、描画、Presentの待ち、表示候補、表示側が使用、再取得可能の順に進む。表示候補が差し替えられた場合は、表示を経ずに再利用へ進む。" width="760" height="365" loading="lazy"><figcaption>描画の完了、表示側への引き渡し、次に使える時点を分けて追います。<a href="/study/images/graphics/swap-chain-image-lifecycle.svg" target="_blank" rel="noopener noreferrer">画像の流れを拡大</a></figcaption></figure><ol><li><strong>取得する。</strong> <code>vkAcquireNextImageKHR</code> がスワップチェーン画像の番号を返します。取得に対応するセマフォやフェンスで利用できる時点を確認し、最初の画像アクセスを順序付けます。</li><li><strong>描いて表示を依頼する。</strong> GPUの描画コマンドは画像に書き込み、表示に必要なレイアウトへ遷移させます。<code>vkQueuePresentKHR</code> に、描画と遷移が済むまで待つセマフォを指定します。APIが戻った時点と、表示エンジンが画像を使う時点は別です。</li><li><strong>表示側が使い終えた画像を再取得する。</strong> 表示方式によっては、候補だった画像がより新しい画像に差し替えられ、画面に出ずに再利用できる場合もあります。どちらの場合も、アプリは次の取得とその同期を経てから同じ画像に書き込みます。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/vkQueuePresentKHR.html" target="_blank" rel="noreferrer">VulkanのPresent API</a> · <a href="https://docs.vulkan.org/guide/latest/swapchain_semaphore_reuse.html" target="_blank" rel="noreferrer">KhronosのPresent待ちセマフォ再利用ガイド</a></li></ol><p>「バッファを3枚にする」のような設定を読むときは、次の三つを分けます。</p><table tabindex="0"><thead><tr><th>数えるもの</th><th>何を表すか</th></tr></thead><tbody><tr><td>スワップチェーンの画像数</td><td>描画先として使い回す画像の枚数。描画中、表示待ち、表示側で使用中などの画像を含む</td></tr><tr><td>フレームスロット数</td><td>コマンドバッファやフレームごとの定数領域などを使い回す枠の数。通常はその枠のGPU処理の完了を確認してから再利用する</td></tr><tr><td>表示待ちの件数</td><td>表示側へ渡した候補のうち、まだ選ばれていない件数。候補を積むか差し替えるかで変わる</td></tr></tbody></table><p>ダブルバッファリングやトリプルバッファリングという名前を見たら、画像の枚数と表示モードをそれぞれ確認します。画像が足りないときは取得に待ちが生じ得ます。画像を増やすと描画を進められる場合がありますが、順番待ちの候補まで増えると、入力を反映した絵が遅れて画面に出ることがあります。<a href="https://docs.vulkan.org/samples/latest/samples/performance/swapchain_images/README.html" target="_blank" rel="noreferrer">Khronosのスワップチェーン画像数の解説</a> · <a href="/study/graphics/capstone/02-device.html">Vulkanで画像とフレームスロットを分ける実装例</a></p><h2 id="画面を上から下へ読み出す途中で切り替わると" tabindex="-1">画面を上から下へ読み出す途中で切り替わると <a class="header-anchor" href="#画面を上から下へ読み出す途中で切り替わると" aria-label="Permalink to &quot;画面を上から下へ読み出す途中で切り替わると&quot;">​</a></h2><p>上から下へ順に画像を読み出す画面を考えます。この読み出しを<strong>スキャンアウト</strong>と呼びます。固定60 Hzでは1回の更新が約16.67 msごとに始まります。読み出しの途中で参照する画像を切り替えると、上の行は古い絵、下の行は新しい絵になります。動く物の位置が境目でずれて見える現象が<strong>ティアリング</strong>です。VSyncは、次の読み出しまでの垂直ブランクに切り替えを合わせて、1回の走査で同じ絵を使う方法です。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPresentModeKHR.html" target="_blank" rel="noreferrer">Vulkanの表示モードと垂直ブランク</a></p><h2 id="同じ絵が届いても、表示モードで選ばれる絵が変わる" tabindex="-1">同じ絵が届いても、表示モードで選ばれる絵が変わる <a class="header-anchor" href="#同じ絵が届いても、表示モードで選ばれる絵が変わる" aria-label="Permalink to &quot;同じ絵が届いても、表示モードで選ばれる絵が変わる&quot;">​</a></h2><p>Vulkanでは、使える表示モードを出力先のサーフェスごとに問い合わせます。下の三つのうち、対応が必須なのは <code>VK_PRESENT_MODE_FIFO_KHR</code> です。<a href="https://docs.vulkan.org/refpages/latest/refpages/source/VkPresentModeKHR.html" target="_blank" rel="noreferrer">KhronosのVkPresentModeKHR仕様</a></p><table tabindex="0"><thead><tr><th>表示モード</th><th>切り替える時点と選び方</th><th>観察できる違い</th></tr></thead><tbody><tr><td><code>FIFO</code></td><td>更新境界で待ち行列の先頭を一つ選ぶ</td><td>届いた順で表示する。候補がたまると新しい絵ほど待つ</td></tr><tr><td><code>MAILBOX</code></td><td>更新境界で1枠の最新候補を選ぶ。新着が待ち候補を差し替える</td><td>直近の入力を反映した絵を選びやすい。差し替えられた絵は表示されない</td></tr><tr><td><code>IMMEDIATE</code></td><td>垂直ブランクを待たず、使える絵に切り替える</td><td>1回の走査に複数の絵が混ざり、ティアリングが起こり得る</td></tr></tbody></table><p>固定60 Hzの例で、最初は絵Aが表示され、次の絵BからGが順に4、11、23、30、39、47 msで表示可能になります。16.67 msの境界でFIFOは先に届いたBを選び、Cを待ち行列に残します。MAILBOXはBをCに差し替えているので、Cを選びます。IMMEDIATEではこの走査がCで始まり、23 msにD、30 msにEへ切り替わります。</p><figure class="study-figure"><img src="'+o+'" alt="仮想60 Hzの約16.67から33.33ミリ秒の走査。FIFOは全面がB、MAILBOXは全面がC。IMMEDIATEは上38パーセントがC、次がD、80パーセントから下がEで、縦棒の位置が二つの境界でずれている。" width="760" height="350" loading="lazy"><figcaption>約16.67〜33.33 msの1回の走査を比較。IMMEDIATEの境目は、その走査中に別の絵が表示可能になった時点です。<a href="/study/images/graphics/swap-chain-presentation-modes.svg" target="_blank" rel="noopener noreferrer">3つの表示モードの図を拡大</a></figcaption></figure><p>最後のGは43 msの入力を反映し、47 msに表示可能になります。FIFOでは先行する候補の順番を待つので、最初の行に現れるのは100 ms（入力から57 ms）です。MAILBOXではGが待ち候補を差し替え、50 msの境界で現れます（7 ms）。IMMEDIATEでは47 msに走査中の行から切り替わります（4 ms）。</p><p>この例は、十分な数の画像があり、OSの画面合成を挟まず、1更新の全区間を使って上から下へ一定の速さで走査するモデルです。遅延として数えるのは、入力のサンプリングからその絵が最初に使われた行までです。実機のパネル応答や入力機器の遅延はこの計算の範囲外です。更新ごとの候補と走査結果を実験で追えます。<a href="/study/practice/graphics/swap-chain-observation.html">表示モードを比べる実践</a></p><h2 id="windowsのpresentと可変リフレッシュレート" tabindex="-1">WindowsのPresentと可変リフレッシュレート <a class="header-anchor" href="#windowsのpresentと可変リフレッシュレート" aria-label="Permalink to &quot;WindowsのPresentと可変リフレッシュレート&quot;">​</a></h2><p>DXGIのフリップモデルで <code>Present(1, 0)</code> を使うと、提示を垂直ブランクに同期します。<code>Present(0, ...)</code> のフリップキューでは、後の提示によって待ち候補が省略される場合があります。ウィンドウやボーダーレスでティアリングを許可する場合は、対応を照会し、作成時の <code>DXGI_SWAP_CHAIN_FLAG_ALLOW_TEARING</code> と、<code>SyncInterval = 0</code> での <code>DXGI_PRESENT_ALLOW_TEARING</code> を組み合わせます。DXGIのフラグとVulkanの表示モードは、それぞれのAPIの規則で読みます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/dxgi/nf-dxgi-idxgiswapchain-present" target="_blank" rel="noreferrer">DXGIのPresentとフリップキュー</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddxgi/dxgi-present" target="_blank" rel="noreferrer">DXGI_PRESENTのフラグ</a></p><p>**可変リフレッシュレート（VRR）**では、対応範囲内で画面の更新間隔そのものを変えられます。DXGIではVRR対応経路を使うためにティアリングを許可する設定が必要です。実際に途中で絵が切り替わるかは、VRRの動作範囲、画面モード、合成の経路などに依存します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddxgi/variable-refresh-rate-displays" target="_blank" rel="noreferrer">DXGIのVRR対応手順</a></p><p>描画は速いのに操作が遅れて見えるときは、入力を読んだ時刻、GPUで描き終えた時刻、画面に出始める時刻を分けて測ります。表示待ちが増えているなら、DXGIの待機可能なスワップチェーンを使い、次のフレームを受け付けられる通知を待ってから入力を読み、描画を始める方法があります。安定性も確認するには、表示間隔の長い箇所と合わせて見ます。<a href="https://learn.microsoft.com/en-us/windows/uwp/gaming/reduce-latency-with-dxgi-1-3-swap-chains" target="_blank" rel="noreferrer">MicrosoftのDXGIでの遅延低減</a> · <a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a></p>',22)])])}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
